package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"log/slog"
	"time"

	"github.com/mellifera/mellifera/internal/store"
)

// The watch-ledger backfill (recommendation-sorting follow-up): the
// completion detector fires ONLY on new OnProgress writes, so every
// playback_progress row that predates the detector's deploy carries no
// watched_items row — completed() is false for it and it keeps scoring the
// InProgress resume bonus on the recommendations it should have left. The
// backfill reconciles that stock exactly once per boot: every positive
// progress row not yet in the ledger whose position reaches the detector's
// own completion predicate (≥ watchedDurationFloor of the STORED ffprobe
// duration; no stored duration ⇒ never backfills — the honest absence)
// inserts its idempotent ledger row and pokes the recs wake, so the tags
// learn through the SAME apply path a live completion takes. Boot-only by
// construction — main runs it before the janitor's boot pass, never per
// tick: a per-tick walk would turn the stock read into a permanent N+1 for
// a set that only shrinks. Every failure is log-and-skip: backfill is never
// load-bearing, and the next boot (or the next live write past the floor)
// retries the remainder.
func newRecsBackfill(st *store.Store) func(context.Context) {
	return func(ctx context.Context) {
		ledgered, err := st.ListWatched(ctx)
		if err != nil {
			slog.Warn("recs backfill: list watched failed", "error", err)
			return
		}
		done := make(map[string]struct{}, len(ledgered))
		for _, id := range ledgered {
			done[id] = struct{}{}
		}
		rows, err := st.ListProgressAll(ctx)
		if err != nil {
			slog.Warn("recs backfill: list progress failed", "error", err)
			return
		}
		backfilled := 0
		for _, p := range rows {
			if _, ok := done[p.ItemID]; ok {
				continue // already in the ledger — the PK dedupe stays upstream
			}
			it, err := st.GetItem(ctx, p.ItemID)
			if err != nil {
				if !errors.Is(err, sql.ErrNoRows) {
					slog.Warn("recs backfill: item lookup failed", "item", p.ItemID, "error", err)
				}
				continue // vanished row — the tolerant reads already skip it
			}
			var doc map[string]any
			if err := json.Unmarshal(it.Document, &doc); err != nil {
				slog.Warn("recs backfill: stored document unreadable", "item", p.ItemID, "error", err)
				continue
			}
			dur, ok := thumbProbeDuration(doc["ffprobe"])
			if !ok {
				continue // no stored duration — the documented honest absence
			}
			if float64(p.PositionSeconds) < watchedDurationFloor*dur {
				continue // still mid-watch — the resume bonus is CORRECT here
			}
			if err := st.InsertWatched(ctx, p.ItemID, it.LibraryID, watchSeriesPath(doc), backfillStamp(p.UpdatedAt)); err != nil {
				slog.Warn("recs backfill: insert watched failed", "item", p.ItemID, "error", err)
				continue
			}
			backfilled++
		}
		if backfilled > 0 {
			slog.Info("recs backfill: reconciled pre-existing completions into the watch ledger", "rows", backfilled)
			notifyRecs()
		}
	}
}

// backfillStamp derives a backfilled row's completed_at from the progress
// write's own RFC3339Nano stamp — the best available completion fact (the
// watch finished at, or before, that write) — falling back to now when the
// stamp is unparseable. The learning queue orders by completed_at, so the
// stock rows land in their historical order instead of all-at-boot order.
func backfillStamp(updatedAt string) time.Time {
	if t, err := time.Parse(time.RFC3339Nano, updatedAt); err == nil {
		return t
	}
	return time.Now().UTC()
}
